331	/// Check if a creature has protection from a specific subtype.
332	fn has_protection_from(state: &GameState, creature_id: ObjectId, subtype: &str, registry: &CardRegistry) -> bool {
333	    for source in state.objects.values() {
334	        if source.zone != crate::types::Zone::Battlefield {
335	            continue;
336	        }
337	        let effects = if let Some(ref instance_effects) = source.instance_continuous_effects {
338	            instance_effects.clone()
339	        } else if let Some(behavior) = registry.get(source.card_id) {
340	            behavior.card_data().continuous_effects
341	        } else {
342	            continue;
343	        };
344	        for effect in &effects {
345	            if let crate::types::ContinuousEffect::ProtectionFromSubtype { subtype: prot_sub, scope } = effect {
346	                if prot_sub == subtype && state.effect_applies_to(creature_id, scope, source.id, source.controller, registry) {
347	                    return true;
348	                }
349	            }
350	        }
351	    }
352	    false
353	}
354	
355	/// Get all subtypes of a creature (from both card data and object-level subtypes).
356	fn get_subtypes(state: &GameState, creature_id: ObjectId, registry: &CardRegistry) -> Vec<String> {
357	    let mut subtypes = Vec::new();
358	    if let Some(obj) = state.get_object(creature_id) {
359	        subtypes.extend(obj.subtypes.iter().cloned());
360	        if let Some(data) = registry.card_data(obj.card_id) {
361	            for s in &data.subtypes {
362	                if !subtypes.contains(s) {
363	                    subtypes.push(s.clone());
364	                }
365	            }
366	        }
367	    }
368	    subtypes
369	}
370	
371	/// Check if creature_a has protection from creature_b.
372	/// Checks all protection-from-subtype effects and until-EOT protection grants.
373	fn has_protection_from_creature(state: &GameState, protected: ObjectId, attacker: ObjectId, registry: &CardRegistry) -> bool {
374	    let attacker_subtypes = get_subtypes(state, attacker, registry);
375	
376	    // Check static protection-from-subtype effects.
377	    for subtype in &attacker_subtypes {
378	        if has_protection_from(state, protected, subtype, registry) {
379	            return true;
380	        }
381	    }
382	
383	    // Check static ProtectionFrom (filter-based) effects.
384	    for source in state.objects.values() {
385	        if source.zone != crate::types::Zone::Battlefield {
386	            continue;
387	        }
388	        let effects = if let Some(ref instance_effects) = source.instance_continuous_effects {
389	            instance_effects.clone()
390	        } else if let Some(behavior) = registry.get(source.card_id) {
391	            behavior.card_data().continuous_effects
392	        } else {
393	            continue;
394	        };
395	        for effect in &effects {
396	            if let crate::types::ContinuousEffect::ProtectionFrom { filter, scope } = effect {
397	                if state.effect_applies_to(protected, scope, source.id, source.controller, registry) {
398	                    if state.matches_filter(attacker, filter, source.controller, registry) {
399	                        return true;
400	                    }
401	                }
402	            }
403	        }
404	    }
405	
406	    // Check until-end-of-turn protection grants.
407	    for prot in &state.until_end_of_turn_protection {
408	        if prot.target == protected {
409	            // Check if the attacker matches the filter.
410	            // Use controller of the protected creature for filter context.
411	            let controller = state.get_object(protected).map(|o| o.controller).unwrap_or(crate::ids::PlayerId(0));
412	            if state.matches_filter(attacker, &prot.filter, controller, registry) {
413	                return true;
414	            }
415	        }
416	    }
417	
418	    false
419	}
