552	/// Clean up combat state at end of combat.
553	pub fn end_combat(state: &mut GameState) {
554	    // Process delayed exile triggers (e.g., Geist of Saint Traft's Angel token).
555	    // These fire independently of the source permanent's presence on the battlefield.
556	    let exiles: Vec<_> = state.end_of_combat_exiles.drain(..).collect();
557	    for exile_id in exiles {
558	        if state.get_object(exile_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
559	            state.move_object(exile_id, Zone::Exile);
560	            state.log(crate::state::LogLevel::Event,
561	                "Token exiled at end of combat (delayed trigger)".into());
562	        }
563	    }
564	    state.combat = None;
565	}
