567	/// Get all creatures a player controls that are eligible to attack.
568	/// Checks keywords (defender, haste) and continuous effects (Pacifism).
569	pub fn eligible_attackers(state: &GameState, player: PlayerId, registry: &CardRegistry) -> Vec<ObjectId> {
570	    state.objects.values()
571	        .filter(|o| {
572	            o.zone == Zone::Battlefield
573	                && o.controller == player
574	                && o.power.is_some()
575	                && !o.tapped
576	                // Haste overrides summoning sickness.
577	                && (!o.summoning_sick || state.has_keyword(o.id, Keyword::Haste, registry))
578	                // Defender can't attack.
579	                && !state.has_keyword(o.id, Keyword::Defender, registry)
580	                // Check aura-based restrictions (Pacifism).
581	                && state.can_attack(o.id, registry)
582	        })
583	        .map(|o| o.id)
584	        .collect()
585	}
