2633	pub fn setup_game(config: &GameConfig, registry: &CardRegistry) -> GameState {
2634	    let num_players = config.player_names.len() as u8;
2635	    let mut state = GameState::new(num_players);
2636	
2637	    // Set starting life.
2638	    for p in &mut state.players {
2639	        p.life = config.starting_life;
2640	    }
2641	
2642	    // Create card objects for each player's deck.
2643	    let mut rng = rand::thread_rng();
2644	    for (player_idx, decklist) in config.decklists.iter().enumerate() {
2645	        let player_id = PlayerId(player_idx as u8);
2646	        let mut library_ids = Vec::new();
2647	
2648	        for (card_name, count) in &decklist.entries {
2649	            let card_id = registry.get_id_by_name(card_name)
2650	                .unwrap_or_else(|| panic!("Unknown card: {}", card_name));
2651	
2652	            let card_data = registry.card_data(card_id).expect("card must be in registry");
2653	
2654	            // Derive colors from mana cost.
2655	            let colors: Vec<Color> = card_data.cost.as_ref()
2656	                .map(|cost| {
2657	                    let mut c = Vec::new();
2658	                    for sym in &cost.symbols {
2659	                        if let ManaSymbol::Colored(color) = sym {
2660	                            if !c.contains(color) {
2661	                                c.push(*color);
2662	                            }
2663	                        }
2664	                    }
2665	                    c
2666	                })
2667	                .unwrap_or_default();
2668	
2669	            for _ in 0..*count {
2670	                let obj_id = state.create_object(
2671	                    card_id,
2672	                    player_id,
2673	                    Zone::Library,
2674	                    card_data.power,
2675	                    card_data.toughness,
2676	                );
2677	                let obj = state.get_object_mut(obj_id).expect("object must exist for library draw");
2678	                obj.colors = colors.clone();
2679	                obj.name = card_name.clone();
2680	                obj.keywords = card_data.keywords.clone();
2681	                obj.card_types = card_data.card_types.clone();
2682	                library_ids.push(obj_id);
2683	            }
2684	        }
2685	
2686	        // Shuffle the library.
2687	        library_ids.shuffle(&mut rng);
2688	        state.get_player_mut(player_id).library_order = library_ids;
2689	    }
2690	
2691	    state.log(LogLevel::Milestone, "Game started".into());
2692	
2693	    // Draw opening hands (7 cards each).
2694	    for player_idx in 0..num_players {
2695	        let player_id = PlayerId(player_idx);
2696	        draw_cards(&mut state, player_id, 7);
2697	    }
2698	
2699	    state.events.push(GameEvent::GameStarted);
2700	    state.log(LogLevel::Milestone, format!("── Turn 1 (p0) ──"));
2701	    state
