2705	pub fn draw_cards(state: &mut GameState, player: PlayerId, count: usize) {
2706	    let mut drawn = 0;
2707	    for _ in 0..count {
2708	        let card_id = {
2709	            let player_state = state.get_player_mut(player);
2710	            player_state.draw_top_card()
2711	        };
2712	        match card_id {
2713	            Some(id) => {
2714	                state.move_object(id, Zone::Hand);
2715	                state.events.push(GameEvent::CardDrawn { player, object: id });
2716	                drawn += 1;
2717	            }
